<script setup lang="ts">import{onMounted,ref}from'vue';import{request}from'../api/client';interface Call{call_no:string;initiator_name:string;call_type:string;status:string;participant_count:number;started_at?:string;ended_at?:string;end_reason:string;created_at:string}const items=ref<Call[]>([]);onMounted(async()=>items.value=await request<Call[]>('/v1/ops/calls'))</script><template><div class="page"><div class="heading"><div><h1>音视频</h1><p>LiveKit 通话与会议记录</p></div></div><div class="table"><table><thead><tr><th>发起人</th><th>类型</th><th>参与人数</th><th>状态</th><th>开始</th><th>结束原因</th></tr></thead><tbody><tr v-for="c in items" :key="c.call_no"><td>{{c.initiator_name}}<small>{{c.call_no}}</small></td><td>{{c.call_type==='video'?'视频':'语音'}}</td><td>{{c.participant_count}}</td><td>{{c.status}}</td><td>{{new Date(c.started_at||c.created_at).toLocaleString()}}</td><td>{{c.end_reason||'-'}}</td></tr></tbody></table></div></div></template><style scoped>@import '../design/admin-page.css';</style>
